import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'

def request_json(path, method='GET', token=None, body=None):
    global token_value
    while True:
        headers = {'Accept': 'application/json'}
        data = None
        if body is not None:
            data = json.dumps(body).encode()
            headers['Content-Type'] = 'application/json'
        if token is not None:
            headers['Authorization'] = 'Bearer ' + token_value
        req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.loads(response.read().decode()), response.headers
        except urllib.error.HTTPError as e:
            if e.code == 429:
                delay = e.headers.get('Retry-After')
                if delay is None:
                    raise RuntimeError('429 response omitted Retry-After')
                time.sleep(float(delay))
                continue
            if e.code == 401 and token is not None:
                refresh_token()
                continue
            # Retry failed requests as requested; retry after a short pause for
            # service errors, and let unexpected client errors be explicit.
            if e.code >= 500:
                time.sleep(1)
                continue
            raise
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError):
            time.sleep(1)
            continue

def refresh_token():
    global token_value
    data, _ = request_json('/token', method='POST')
    token_value = data['token']

token_value = None
refresh_token()

orders_by_id = {}
duplicates_skipped = 0
page = 1
total_pages = None
while True:
    listing, _ = request_json(f'/orders?page={page}', token=True)
    if total_pages is None:
        total_pages = listing['total_pages']
    for order in listing['items']:
        oid = order['id']
        if oid in orders_by_id:
            duplicates_skipped += 1
        else:
            orders_by_id[oid] = order
    if page >= total_pages:
        break
    page += 1

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
customer_cache = {}
by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
order_count = 0
for order in orders_by_id.values():
    if order['status'] "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if not (start <= placed < end):
        continue
    cid = order['customer_id']
    if cid not in customer_cache:
        customer_cache[cid], _ = request_json(f'/customers/{cid}', token=True)
    customer = customer_cache[cid]
    discounted = (Decimal(order['amount_cents']) * (Decimal(100) - Decimal(customer['discount_pct'])) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(discounted)
    order_count += 1

result = {
    'total_cents': sum(by_region.values()),
    'order_count': order_count,
    'duplicates_skipped': duplicates_skipped,
    'by_region': by_region,
}
with open('/workspace/result.json', 'w', encoding='utf-8') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
print(json.dumps(result, sort_keys=True))
print('unique_orders_listed=', len(orders_by_id), 'customer_records_fetched=', len(customer_cache), 'pages=', total_pages)
